import torch, math
def gen(B,C,H,W,g):
    r=lambda *s: torch.randn(*s,generator=g,device='cuda',dtype=torch.float32)
    return [r(B,C,H,W), r(C,1,7,7)/math.sqrt(7), r(C), torch.ones(C,device='cuda'), torch.zeros(C,device='cuda'),
            r(4*C,C)/math.sqrt(C), r(4*C), r(1,1,1,4*C)/math.sqrt(4*C), r(1,1,1,4*C), r(C,4*C)/math.sqrt(4*C), r(C)]
def ref64(a):
    x,dw,dwb,lnw,lnb,W1,b1,gw,gb,W2,b2=[t.double() for t in a]
    C=x.shape[1]
    d=torch.nn.functional.conv2d(x,dw,dwb,padding=3,groups=C).permute(0,2,3,1)
    t=torch.nn.functional.layer_norm(d,(C,),lnw,lnb,1e-6)
    h=torch.nn.functional.gelu(t@W1.t()+b1)
